$serverPath = Join-Path $PSScriptRoot '..\server\src\hadith-admin.js'
$server = [IO.File]::ReadAllText($serverPath)
$server = $server.Replace("const{ObjectId}=require('mongodb');", "const{ObjectId}=require('mongodb');`r`nconst path=require('path');`r`nconst COMMENTARIES=require(path.join(__dirname,'../../app/src/data/hadeethenc-en.json'));`r`nconst STOP=new Set(['the','a','an','and','or','of','to','in','is','was','were','be','been','by','for','from','that','this','with','his','her','him','he','she','they','it','may','allah','upon','said','reported','messenger','prophet','peace','blessings']);`r`nconst words=value=>new Set(String(value||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(x=>x.length>2&&!STOP.has(x)));`r`nfunction findCommentary(text){const target=words(text);if(target.size<3)return null;let best=null,bestScore=0;for(const row of COMMENTARIES){const candidate=words(row.text);let shared=0;target.forEach(word=>{if(candidate.has(word))shared++});const score=shared/Math.min(target.size,candidate.size);if(shared>=4&&score>bestScore){best=row;bestScore=score}}return bestScore>=.5?best:null;}")
$routeNeedle = "router.get('/api/admin/hadith/existing/:collectionId',admin,async(req,res)=>"
$routeInsert = "router.post('/api/admin/hadith/commentary-match',admin,(req,res)=>{try{const match=findCommentary(req.body.text);res.json({data:match?{explanation:match.explanation||'',source:match.source||'HadeethEnc.com'}:null})}catch(e){res.status(500).json({message:'Unable to match Hadith explanation.'})}});`r`n " + $routeNeedle
if (-not $server.Contains($routeNeedle)) { throw 'Hadith existing route not found.' }
$server = $server.Replace($routeNeedle,$routeInsert)
[IO.File]::WriteAllText($serverPath,$server,[Text.UTF8Encoding]::new($false))

$adminPath = Join-Path $PSScriptRoot '..\admin-panel\app\hadith\page.tsx'
$admin = [IO.File]::ReadAllText($adminPath)
$old = "function edit(row:any,lang=language){const t=lang==='en'?row:row.translations?.[lang]||{};const generatedPronunciation=lang==='en'&&row.arabic&&!t.pronunciation?transliterate(row.arabic):'';setForm({...empty,...row,...t,pronunciation:t.pronunciation||generatedPronunciation,id:row.external?`"`":row.id,collectionId:row.collectionId,collectionName:row.collectionName,arabic:row.arabic,published:row.published!==false});setLanguage(lang);window.scrollTo({top:0,behavior:'smooth'})}"
$new = "async function edit(row:any,lang=language){const t=lang==='en'?row:row.translations?.[lang]||{};const generatedPronunciation=lang==='en'&&row.arabic&&!t.pronunciation?transliterate(row.arabic):'';let explanation=t.explanation||'';let source=t.source||'';if(lang==='en'&&row.external&&!explanation){try{const response=await fetch(API+'/api/admin/hadith/commentary-match',{method:'POST',headers:headers(),body:JSON.stringify({text:row.text,arabic:row.arabic})}),result=await response.json();if(response.ok&&result.data){explanation=result.data.explanation||'';source=result.data.source||source}}catch{}}setForm({...empty,...row,...t,explanation,source,pronunciation:t.pronunciation||generatedPronunciation,id:row.external?`"`":row.id,collectionId:row.collectionId,collectionName:row.collectionName,arabic:row.arabic,published:row.published!==false});setLanguage(lang);window.scrollTo({top:0,behavior:'smooth'})}"
if (-not $admin.Contains($old)) { throw 'Admin edit function not found.' }
$admin = $admin.Replace($old,$new)
[IO.File]::WriteAllText($adminPath,$admin,[Text.UTF8Encoding]::new($false))
